fn main() {
    #[cfg(feature = "jit")]
    {
        match reth_node_ethereum::node::maybe_run_jit_helper() {
            Ok(std::ops::ControlFlow::Break(())) => return,
            Ok(std::ops::ControlFlow::Continue(())) => {}
            Err(err) => {
                eprintln!("Error: {err:?}");
                std::process::exit(1);
            }
        }
    }

    reth_cli_util::sigsegv_handler::install();

    // Enable backtraces unless a RUST_BACKTRACE value has already been explicitly provided.
    if std::env::var_os("RUST_BACKTRACE").is_none() {
        unsafe { std::env::set_var("RUST_BACKTRACE", "1") };
    }

    if let Err(err) = Cli::<EthereumChainSpecParser>::parse().run(async move |builder, _| {
        info!(target: "reth::cli", "Launching node");
        let handle = builder.node(EthereumNode::default()).launch_with_debug_capabilities().await?;

        handle.wait_for_node_exit().await
    }) {
        eprintln!("Error: {err:?}");
        std::process::exit(1);
    }
}

pub async fn execute<L>(self, ctx: CliContext, launcher: L) -> eyre::Result<()>
where
    L: Launcher<C, Ext>,
{
    tracing::info!(target: "reth::cli", version = ?version::version_metadata().short_version, "Starting {}",  version::version_metadata().name_client);

    let Self {
        datadir,
        config,
        chain,
        metrics,
        instance,
        with_unused_ports,
        network,
        rpc,
        txpool,
        builder,
        debug,
        db,
        dev,
        pruning,
        engine,
        era,
        static_files,
        storage,
        jit,
        ext,
    } = self;

    engine.validate()?;

    // set up node config
    let mut node_config = NodeConfig {
        datadir,
        config,
        chain,
        metrics,
        instance,
        network,
        rpc,
        txpool,
        builder,
        debug,
        db,
        dev,
        pruning,
        engine,
        era,
        static_files,
        storage,
        jit,
    };

    let data_dir = node_config.datadir();
    let db_path = data_dir.db();

    tracing::info!(target: "reth::cli", path = ?db_path, "Opening database");
    let database = init_db(db_path.clone(), self.db.database_args())?
        .with_metrics_if(self.db.metrics_enabled());

    if with_unused_ports {
        node_config = node_config.with_unused_ports();
    }

    let builder = NodeBuilder::new(node_config)
        .with_database(database)
        .with_launch_context(ctx.task_executor);

    launcher.entrypoint(builder, ext).await
}

async fn launch_node<N, DB, T, CB, AO>(
    self,
    target: NodeBuilderWithComponents<T, CB, AO>,
) -> eyre::Result<NodeHandle<NodeAdapter<T, CB::Components>, AO>>
where
    N: Node<RethFullAdapter<DB, N>> + NodeTypesForProvider,
    DB: Database + DatabaseMetrics + Clone + Unpin + 'static,
    T: FullNodeTypes<
        Types = N,
        Provider = BlockchainProvider<NodeTypesWithDBAdapter<N, DB>>,
        DB = DB,
    >,
    CB: NodeComponentsBuilder<T>,
    AO: RethRpcAddOns<NodeAdapter<T, CB::Components>>
        + EngineValidatorAddOn<NodeAdapter<T, CB::Components>>,
{
    let Self { ctx, engine_tree_config } = self;
    let NodeBuilderWithComponents {
        adapter: NodeTypesAdapter { database },
        rocksdb_provider,
        components_builder,
        add_ons: AddOns { hooks, exexs: installed_exex, add_ons },
        config,
    } = target;
    let NodeHooks { on_component_initialized, on_node_started, .. } = hooks;

    // Create the overlay manager that will be shared across the provider and engine.
    let overlay_manager = OverlayManager::<N::Primitives>::new(
        ctx.task_executor.state_trie_overlay_worker_pool(),
    );
    let disabled_stages = N::disabled_stages();

    // setup the launch context
    let ctx = ctx
        .with_configured_globals(engine_tree_config.reserved_cpu_cores())
        // load the toml config
        .with_loaded_toml_config(config)?
        // add resolved peers
        .with_resolved_peers()?
        // attach the database
        .attach(database.clone())
        // ensure certain settings take effect
        .with_adjusted_configs()
        // Create the provider factory with the shared overlay manager
        .with_provider_factory::<_, <CB::Components as NodeComponents<T>>::Evm>(
            overlay_manager.clone(),
            rocksdb_provider,
            disabled_stages,
        )
        .await?
        .inspect(|_| {
            info!(target: "reth::cli", "Database opened");
        })
        .with_prometheus_server().await?
        .inspect(|this| {
            debug!(target: "reth::cli", chain=%this.chain_id(), genesis=?this.genesis_hash(), "Initializing genesis");
        })
        .with_genesis()?
        .inspect(|this: &LaunchContextWith<Attached<WithConfigs<<T::Types as NodeTypes>::ChainSpec>, _>>| {
            info!(target: "reth::cli", "\n{}", this.chain_spec().display_hardforks());
            let settings = this.provider_factory().cached_storage_settings();
            let pruning_mode =
                PruneConfigKind::from_config(&this.prune_config(), this.chain_spec().as_ref()).as_str();
            info!(target: "reth::cli", ?settings, ?pruning_mode, "Loaded storage settings");
        })
        .with_metrics_task()
        // passing FullNodeTypes as type parameter here so that we can build
        // later the components.
        .with_blockchain_db::<T, _>(move |provider_factory| {
            Ok(BlockchainProvider::new(provider_factory)?)
        })?
        .with_components(components_builder, on_component_initialized).await?;

impl<Node, PoolB, PayloadB, NetworkB, ExecB, ConsB> NodeComponentsBuilder<Node>
    for ComponentsBuilder<Node, PoolB, PayloadB, NetworkB, ExecB, ConsB>
where
    Node: FullNodeTypes,
    PoolB: PoolBuilder<Node, ExecB::EVM, Pool: TransactionPool>,
    NetworkB: NetworkBuilder<
        Node,
        PoolB::Pool,
        Network: FullNetwork<
            Primitives: NetPrimitivesFor<
                PrimitivesTy<Node::Types>,
                PooledTransaction = PoolPooledTx<PoolB::Pool>,
            >,
        >,
    >,
    PayloadB: PayloadServiceBuilder<Node, PoolB::Pool, ExecB::EVM>,
    ExecB: ExecutorBuilder<Node>,
    ConsB: ConsensusBuilder<Node>,
{
    type Components =
        Components<Node, NetworkB::Network, PoolB::Pool, ExecB::EVM, ConsB::Consensus>;

    async fn build_components(
        self,
        context: &BuilderContext<Node>,
    ) -> eyre::Result<Self::Components> {
        let Self {
            pool_builder,
            payload_builder,
            network_builder,
            executor_builder,
            consensus_builder,
            _marker,
        } = self;

        let evm_config = executor_builder.build_evm(context).await?;
        let pool = pool_builder.build_pool(context, evm_config.clone()).await?;
        let network = network_builder.build_network(context, pool.clone()).await?;
        let payload_builder_handle = payload_builder
            .spawn_payload_builder_service(context, pool.clone(), evm_config.clone())
            .await?;
        let consensus = consensus_builder.build_consensus(context).await?;

        Ok(Components {
            transaction_pool: pool,
            evm_config,
            network,
            payload_builder_handle,
            consensus,
        })
    }
}

impl<N: ProviderNodeTypes> PipelineSync<N> {
    /// Create a new instance.
    pub fn new(pipeline: Pipeline<N>, pipeline_task_spawner: Runtime) -> Self {
        Self {
            pipeline_task_spawner,
            pipeline_state: PipelineState::Idle(Some(Box::new(pipeline))),
            pending_pipeline_target: None,
        }
    }

    /// Returns `true` if a pipeline target is queued and will be triggered on the next `poll`.
    #[expect(dead_code)]
    const fn is_pipeline_sync_pending(&self) -> bool {
        self.pending_pipeline_target.is_some() && self.pipeline_state.is_idle()
    }

    /// Returns `true` if the pipeline is idle.
    const fn is_pipeline_idle(&self) -> bool {
        self.pipeline_state.is_idle()
    }

    /// Returns `true` if the pipeline is active.
    const fn is_pipeline_active(&self) -> bool {
        !self.is_pipeline_idle()
    }

    /// Sets a new target to sync the pipeline to.
    ///
    /// But ensures the target is not the zero hash.
    fn set_pipeline_sync_target(&mut self, target: PipelineTarget) {
        if target.sync_target().is_some_and(|target| target.is_zero()) {
            trace!(
                target: "consensus::engine::sync",
                "Pipeline target cannot be zero hash."
            );
            // precaution to never sync to the zero hash
            return
        }
        self.pending_pipeline_target = Some(target);
    }

    /// This will spawn the pipeline if it is idle and a target is set or if the pipeline is set to
    /// run continuously.
    fn try_spawn_pipeline(&mut self) -> Option<BackfillEvent> {
        match &mut self.pipeline_state {
            PipelineState::Idle(pipeline) => {
                let target = self.pending_pipeline_target.take()?;
                let (tx, rx) = oneshot::channel();

                let pipeline = pipeline.take().expect("exists");
                self.pipeline_task_spawner.spawn_critical_blocking_task(
                    "pipeline task",
                    async move {
                        let result = pipeline.run_as_fut(Some(target)).await;
                        let _ = tx.send(result);
                    },
                );
                self.pipeline_state = PipelineState::Running(rx);

                Some(BackfillEvent::Started(target))
            }
            PipelineState::Running(_) => None,
        }
    }

    /// Advances the pipeline state.
    ///
    /// This checks for the result in the channel, or returns pending if the pipeline is idle.
    fn poll_pipeline(&mut self, cx: &mut Context<'_>) -> Poll<BackfillEvent> {
        let res = match self.pipeline_state {
            PipelineState::Idle(_) => return Poll::Pending,
            PipelineState::Running(ref mut fut) => {
                ready!(fut.poll_unpin(cx))
            }
        };
        let ev = match res {
            Ok((pipeline, result)) => {
                self.pipeline_state = PipelineState::Idle(Some(Box::new(pipeline)));
                BackfillEvent::Finished(result)
            }
            Err(why) => {
                // failed to receive the pipeline
                BackfillEvent::TaskDropped(why.to_string())
            }
        };
        Poll::Ready(ev)
    }
}

impl<N: ProviderNodeTypes> BackfillSync for PipelineSync<N> {
    fn on_action(&mut self, event: BackfillAction) {
        match event {
            BackfillAction::Start(target) => self.set_pipeline_sync_target(target),
        }
    }

    fn poll(&mut self, cx: &mut Context<'_>) -> Poll<BackfillEvent> {
        // try to spawn a pipeline if a target is set
        if let Some(event) = self.try_spawn_pipeline() {
            return Poll::Ready(event)
        }

        // make sure we poll the pipeline if it's active, and return any ready pipeline events
        if self.is_pipeline_active() {
            // advance the pipeline
            if let Poll::Ready(event) = self.poll_pipeline(cx) {
                return Poll::Ready(event)
            }
        }

        Poll::Pending
    }
}

/// Unwind the stages to the target block (exclusive).
///
/// If the unwind is due to a bad block the number of that block should be specified.
pub fn unwind(
    &mut self,
    to: BlockNumber,
    bad_block: Option<BlockNumber>,
) -> Result<(), PipelineError> {
    // Add validation before starting unwind
    let (latest_block, prune_modes, checkpoints) = {
        let provider = self.provider_factory.provider()?;
        (
            provider.last_block_number()?,
            provider.prune_modes_ref().clone(),
            provider.get_prune_checkpoints()?,
        )
    };
    prune_modes.ensure_unwind_target_unpruned(latest_block, to, &checkpoints)?;

    // Unwind stages in reverse order of execution
    let unwind_pipeline = self.stages.iter_mut().rev();

    // Legacy Engine: This prevents a race condition in which the `StaticFileProducer` could
    // attempt to proceed with a finalized block which has been unwinded
    let _locked_sf_producer = self.static_file_producer.lock();

    let mut provider_rw =
        self.provider_factory.unwind_provider_rw()?.disable_long_read_transaction_safety();

    for stage in unwind_pipeline {
        let stage_id = stage.id();
        let span = info_span!("Unwinding", stage = %stage_id);
        let _enter = span.enter();

        let mut checkpoint = provider_rw.get_stage_checkpoint(stage_id)?.unwrap_or_default();
        if checkpoint.block_number < to {
            debug!(
                target: "sync::pipeline",
                from = %checkpoint.block_number,
                %to,
                "Unwind point too far for stage"
            );
            self.event_sender.notify(PipelineEvent::Skipped { stage_id });

            continue
        }

        info!(
            target: "sync::pipeline",
            from = %checkpoint.block_number,
            %to,
            ?bad_block,
            "Starting unwind"
        );
        while checkpoint.block_number > to {
            let unwind_started_at = Instant::now();
            let input = UnwindInput { checkpoint, unwind_to: to, bad_block };
            self.event_sender.notify(PipelineEvent::Unwind { stage_id, input });

            let output = stage.unwind(&provider_rw, input);
            match output {
                Ok(unwind_output) => {
                    checkpoint = unwind_output.checkpoint;
                    info!(
                        target: "sync::pipeline",
                        stage = %stage_id,
                        unwind_to = to,
                        progress = checkpoint.block_number,
                        done = checkpoint.block_number == to,
                        "Stage unwound"
                    );

                    provider_rw.save_stage_checkpoint(stage_id, checkpoint)?;

                    // Notify event listeners and update metrics.
                    self.event_sender
                        .notify(PipelineEvent::Unwound { stage_id, result: unwind_output });

                    if let Some(metrics_tx) = &mut self.metrics_tx {
                        let _ = metrics_tx.send(MetricEvent::StageCheckpoint {
                            stage_id,
                            checkpoint,
                            // We assume it was set in the previous execute iteration, so it
                            // doesn't change when we unwind.
                            max_block_number: None,
                            elapsed: unwind_started_at.elapsed(),
                        });
                    }

                    // update finalized and safe block if needed
                    let last_saved_finalized_block_number =
                        provider_rw.last_finalized_block_number()?;

                    // If None, that means the finalized block is not written so we should
                    // always save in that case
                    if last_saved_finalized_block_number.is_none() ||
                        Some(checkpoint.block_number) < last_saved_finalized_block_number
                    {
                        provider_rw.save_finalized_block_number(BlockNumber::from(
                            checkpoint.block_number,
                        ))?;
                    }

                    let last_saved_safe_block_number = provider_rw.last_safe_block_number()?;

                    if last_saved_safe_block_number.is_none() ||
                        Some(checkpoint.block_number) < last_saved_safe_block_number
                    {
                        provider_rw.save_safe_block_number(BlockNumber::from(
                            checkpoint.block_number,
                        ))?;
                    }

                    provider_rw.commit()?;

                    stage.post_unwind_commit()?;

                    provider_rw = self.provider_factory.unwind_provider_rw()?;
                }
                Err(err) => {
                    self.event_sender.notify(PipelineEvent::Error { stage_id });

                    return Err(PipelineError::Stage(StageError::Fatal(Box::new(err))))
                }
            }
        }
    }

    Ok(())
}

    let full_node = FullNode {
        evm_config: ctx.components().evm_config().clone(),
        pool: ctx.components().pool().clone(),
        network: ctx.components().network().clone(),
        provider: ctx.node_adapter().provider.clone(),
        payload_builder_handle: ctx.components().payload_builder_handle().clone(),
        task_executor: ctx.task_executor().clone(),
        config: ctx.node_config().clone(),
        data_dir: ctx.data_dir().clone(),
        add_ons_handle: RpcHandle {
            rpc_server_handles,
            rpc_registry,
            engine_events,
            beacon_engine_handle,
            engine_shutdown,
        },
    };
    // Notify on node started
    on_node_started.on_event(FullNode::clone(&full_node))?;

    ctx.spawn_ethstats(engine_events_for_ethstats).await?;

    let handle = NodeHandle {
        node_exit_future: NodeExitFuture::new(async { rx.await? }),
        node: full_node,
    };

    Ok(handle)
}

fn try_recover(pooled: Self::Pooled) -> Result<Self, Self::Pooled> {
    pooled.try_into_recovered().map(Self::from_pooled)
}

/// Recovers and converts a pooled transaction using the provided sender recovery cache.
fn try_recover_with_cache(
    pooled: Self::Pooled,
    cache: &reth_evm::SenderRecoveryCache,
) -> Result<Self, Self::Pooled> {
    match cache.recover(&pooled) {
        Ok(signer) => Ok(Self::from_pooled(Recovered::new_unchecked(pooled, signer))),
        Err(_) => Err(pooled),
    }
}

/// Recovers and converts a pooled transaction, using the sender recovery cache if provided.
///
/// Delegates to [`Self::try_recover`] when no cache is configured.
fn try_recover_with_cache_opt(
    pooled: Self::Pooled,
    cache: Option<&reth_evm::SenderRecoveryCache>,
) -> Result<Self, Self::Pooled> {
    match cache {
        Some(cache) => Self::try_recover_with_cache(pooled, cache),
        None => Self::try_recover(pooled),
    }
}

/// Decodes and recovers a raw transaction into this pool transaction type.
///
/// Implementations can override this to avoid constructing the pooled transaction as an
/// intermediate value when the raw representation can be converted directly into `Self`.
/// RPC uses this hook when no sender recovery cache is configured. Override
/// [`Self::recover_raw_transaction_with_cache`] to specialize the cached path as well.
fn recover_raw_transaction(data: &[u8]) -> Result<Self, RawPoolTransactionError> {
    Self::try_recover(Self::decode_raw_transaction(data)?)
        .map_err(|_| RawPoolTransactionError::InvalidTransactionSignature)
}

/// Decodes and recovers a raw pool transaction using the provided sender recovery cache.
///
/// RPC uses this hook when a sender recovery cache is configured. Implementations can override
/// it to reuse the raw bytes or encoded length during recovery and construction. The default
/// implementation decodes and recovers separately; it does not call
/// [`Self::recover_raw_transaction`].
fn recover_raw_transaction_with_cache(
    data: &[u8],
    cache: &reth_evm::SenderRecoveryCache,
) -> Result<Self, RawPoolTransactionError> {
    Self::try_recover_with_cache(Self::decode_raw_transaction(data)?, cache)
        .map_err(|_| RawPoolTransactionError::InvalidTransactionSignature)
}

/// Decodes a raw pooled transaction without recovering its sender.
///
/// The entire input must be consumed; trailing bytes are rejected. Implementations can override
/// this to customize raw decoding independently of sender recovery.
fn decode_raw_transaction(data: &[u8]) -> Result<Self::Pooled, RawPoolTransactionError> {
    if data.is_empty() {
        return Err(RawPoolTransactionError::EmptyRawTransactionData)
    }

    Self::Pooled::decode_2718_exact(data)
        .map_err(|_| RawPoolTransactionError::FailedToDecodeSignedTransaction)
}

/// Returns the transaction by hash.
///
/// Checks the pool and state.
///
/// Returns `Ok(None)` if no matching transaction was found.
#[expect(clippy::complexity)]
fn transaction_by_hash(
    &self,
    hash: B256,
) -> impl Future<
    Output = Result<Option<TransactionSource<ProviderTx<Self::Provider>>>, Self::Error>,
> + Send {
    LoadTransaction::transaction_by_hash(self, hash)
}

fn transaction_by_hash(
    &self,
    hash: B256,
) -> impl Future<
    Output = Result<Option<TransactionSource<ProviderTx<Self::Provider>>>, Self::Error>,
> + Send {
    async move {
        // First, try the RPC cache
        if let Some(cached) = self.cache().get_transaction_by_hash(hash).await &&
            let Some(source) = cached.to_transaction_source()
        {
            return Ok(Some(source));
        }

        // Cache miss - try to find the transaction on disk
        if let Some((tx, meta)) = self
            .spawn_blocking_io(move |this| {
                this.provider()
                    .transaction_by_hash_with_meta(hash)
                    .map_err(Self::Error::from_eth_err)
            })
            .await?
        {
            // Note: we assume this transaction is valid, because it's mined (or
            // part of pending block) and already. We don't need to
            // check for pre EIP-2 because this transaction could be pre-EIP-2.
            let transaction = tx
                .try_into_recovered_unchecked()
                .map_err(|_| EthApiError::InvalidTransactionSignature)?;

            return Ok(Some(TransactionSource::Block {
                transaction,
                index: meta.index,
                block_hash: meta.block_hash,
                block_number: meta.block_number,
                block_timestamp: meta.timestamp,
                base_fee: meta.base_fee,
            }));
        }

        // tx not found on disk, check pool
        if let Some(tx) = self.pool().get(&hash).map(|tx| tx.transaction.clone_into_consensus())
        {
            return Ok(Some(TransactionSource::Pool(tx.into())));
        }

        Ok(None)
    }
}

fn get(&self, tx_hash: &TxHash) -> Option<Arc<ValidPoolTransaction<Self::Transaction>>> {
    self.inner().get(tx_hash)
}

fn get_all(&self, txs: Vec<TxHash>) -> Vec<Arc<ValidPoolTransaction<Self::Transaction>>> {
    self.inner().get_all(txs)
}

fn transaction_event_listener(&self, tx_hash: TxHash) -> Option<TransactionEvents> {
    self.pool.add_transaction_event_listener(tx_hash)
}

fn all_transactions_event_listener(&self) -> AllTransactionsEvents<Self::Transaction> {
    self.pool.add_all_transactions_event_listener()
}

fn pending_transactions_listener_for(&self, kind: TransactionListenerKind) -> Receiver<TxHash> {
    self.pool.add_pending_listener(kind)
}

fn blob_transaction_sidecars_listener(&self) -> Receiver<NewBlobSidecar> {
    self.pool.add_blob_sidecar_listener()
}

fn new_transactions_listener_for(
    &self,
    kind: TransactionListenerKind,
) -> Receiver<NewTransactionEvent<Self::Transaction>> {
    self.pool.add_new_transaction_listener(kind)
}

pub struct EthApiInner<N: RpcNodeCore, Rpc: RpcConvert> {
    /// The components of the node.
    components: N,
    /// All configured Signers
    signers: SignersForRpc<N::Provider, Rpc::Network>,
    /// The async cache frontend for eth related data
    eth_cache: EthStateCache<N::Primitives>,
    /// The async gas oracle frontend for gas price suggestions
    gas_oracle: GasPriceOracle<N::Provider>,
    /// Settings shared by the `eth` RPC helpers.
    settings: EthApiSettings,
    /// The block number at which the node started
    starting_block: U256,
    /// The type that can spawn tasks which would otherwise block.
    task_spawner: Runtime,
    /// Cached pending block if any
    pending_block: Mutex<Option<PendingBlock<N::Primitives>>>,
    /// A pool dedicated to CPU heavy blocking tasks.
    blocking_task_pool: BlockingTaskPool,
    /// Cache for block fees history
    fee_history_cache: FeeHistoryCache<ProviderHeader<N::Provider>>,

    /// Guard for getproof calls
    blocking_task_guard: BlockingTaskGuard,

    /// Semaphore to limit concurrent blocking IO requests (`eth_call`, `eth_estimateGas`, etc.)
    blocking_io_request_semaphore: Arc<Semaphore>,

    /// Transaction broadcast channel
    raw_tx_sender: broadcast::Sender<Bytes>,

    /// Raw transaction forwarder
    raw_tx_forwarder: Option<RpcClient>,

    /// Converter for RPC types.
    converter: Rpc,

    /// Builder for pending block environment.
    next_env_builder: Box<dyn PendingEnvBuilder<N::Evm>>,

    /// Transaction batch sender for batching tx insertions
    tx_batch_sender:
        mpsc::UnboundedSender<BatchTxRequest<<N::Pool as TransactionPool>::Transaction>>,

    /// Blob sidecar converter
    blob_sidecar_converter: BlobSidecarConverter,
}

pub fn new(
    components: N,
    eth_cache: EthStateCache<N::Primitives>,
    gas_oracle: GasPriceOracle<N::Provider>,
    settings: EthApiSettings,
    blocking_task_pool: BlockingTaskPool,
    fee_history_cache: FeeHistoryCache<ProviderHeader<N::Provider>>,
    task_spawner: Runtime,
    converter: Rpc,
    next_env: impl PendingEnvBuilder<N::Evm>,
    raw_tx_forwarder: Option<RpcClient>,
) -> Self {
    let signers = parking_lot::RwLock::new(Default::default());
    // get the block number of the latest block
    let starting_block = U256::from(
        components
            .provider()
            .header_by_number_or_tag(BlockNumberOrTag::Latest)
            .ok()
            .flatten()
            .map(|header| header.number())
            .unwrap_or_default(),
    );

    let (raw_tx_sender, _) = broadcast::channel(DEFAULT_BROADCAST_CAPACITY);

    // Create tx pool insertion batcher
    let (processor, tx_batch_sender) =
        BatchTxProcessor::new(components.pool().clone(), settings.max_batch_size);
    task_spawner.spawn_critical_task("tx-batcher", processor);

    Self {
        components,
        signers,
        eth_cache,
        gas_oracle,
        starting_block,
        task_spawner,
        pending_block: Default::default(),
        blocking_task_pool,
        fee_history_cache,
        blocking_task_guard: BlockingTaskGuard::new(settings.proof_permits),
        blocking_io_request_semaphore: Arc::new(Semaphore::new(
            settings.max_blocking_io_requests,
        )),
        settings,
        raw_tx_sender,
        raw_tx_forwarder,
        converter,
        next_env_builder: Box::new(next_env),
        tx_batch_sender,
        blob_sidecar_converter: BlobSidecarConverter::new(),
    }
}

/// Block related functions for the [`EthApiServer`](crate::EthApiServer) trait in the
/// `eth_` namespace.
pub trait EthBlocks: LoadBlock<RpcConvert: RpcConvert<Primitives = Self::Primitives>> {
    /// Returns the block header for the given block id.
    fn rpc_block_header(
        &self,
        block_id: BlockId,
    ) -> impl Future<Output = Result<Option<RpcHeader<Self::NetworkTypes>>, Self::Error>> + Send
    where
        Self: FullEthApiTypes,
    {
        async move {
            let Some(block) = self.recovered_block(block_id).await? else { return Ok(None) };
            // Header responses omit the block size: https://github.com/ethereum/execution-apis/pull/877
            let header = self.converter().convert_header(block.clone_sealed_header(), None)?;
            Ok(Some(header))
        }
    }

    /// Returns the populated rpc block object for the given block id.
    ///
    /// If `full` is true, the block object will contain all transaction objects, otherwise it will
    /// only contain the transaction hashes.
    fn rpc_block(
        &self,
        block_id: BlockId,
        full: bool,
    ) -> impl Future<Output = Result<Option<RpcBlock<Self::NetworkTypes>>, Self::Error>> + Send
    where
        Self: FullEthApiTypes,
    {
        async move {
            let Some(block) = self.recovered_block(block_id).await? else { return Ok(None) };

            let block = block.clone_into_rpc_block(
                full.into(),
                |tx, tx_info| self.converter().fill(tx, tx_info),
                |header, block_size| self.converter().convert_header(header, Some(block_size)),
            )?;
            Ok(Some(block))
        }
    }

async fn setup_rpc_components<'a, F>(
    self,
    ctx: AddOnsContext<'a, N>,
    ext: F,
) -> eyre::Result<RpcSetupContext<'a, N, EthB::EthApi>>
where
    F: FnOnce(RpcModuleContainer<'_, N, EthB::EthApi>) -> eyre::Result<()>,
{
    let Self { eth_api_builder, engine_api_builder, hooks, .. } = self;

    let engine_api = engine_api_builder.build_engine_api(&ctx).await?;
    let AddOnsContext {
        node,
        config,
        beacon_engine_handle,
        jwt_secret,
        engine_events,
        sender_recovery_cache,
    } = ctx;

    info!(target: "reth::cli", "Engine API handler initialized");

    let cache = EthStateCache::spawn_with(
        node.provider().clone(),
        config.rpc.eth_config().cache,
        node.task_executor().clone(),
    );

    let new_canonical_blocks = node.provider().canonical_state_stream();
    let c = cache.clone();
    node.task_executor().spawn_critical_task("cache canonical blocks task", async move {
        cache_new_blocks_task(c, new_canonical_blocks).await;
    });

    let prewarm_bals = config
        .rpc
        .eth_config()
        .cache
        .prewarm_bals
        .map(|count| (count, node.provider().canonical_state_stream()));

    let eth_config = config.rpc.eth_config().max_batch_size(config.txpool.max_batch_size());
    let ctx = EthApiCtx {
        components: &node,
        config: eth_config,
        cache,
        engine_handle: beacon_engine_handle.clone(),
        sender_recovery_cache,
    };
    let eth_api = eth_api_builder.build_eth_api(ctx).await?;

    if let Some((count, events)) = prewarm_bals {
        node.task_executor().spawn_task(prewarm_new_block_bals_task(
            eth_api.clone(),
            events,
            count,
        ));
    }

    let auth_config = config.rpc.auth_server_config(jwt_secret)?;
    let module_config = config.rpc.transport_rpc_module_config();
    debug!(target: "reth::cli", http=?module_config.http(), ws=?module_config.ws(), "Using RPC module config");

    let (mut modules, mut auth_module, registry) = RpcModuleBuilder::default()
        .with_provider(node.provider().clone())
        .with_pool(node.pool().clone())
        .with_network(node.network().clone())
        .with_executor(node.task_executor().clone())
        .with_evm_config(node.evm_config().clone())
        .with_consensus(node.consensus().clone())
        .build_with_auth_server(
            module_config,
            engine_api,
            eth_api,
            engine_events.clone(),
            beacon_engine_handle.clone(),
        );

    // in dev mode we generate 20 random dev-signer accounts
    if config.dev.dev {
        let signers = DevSigner::from_mnemonic(config.dev.dev_mnemonic.as_str(), 20);
        registry.eth_api().signers().write().extend(signers);
    }

    let mut registry = RpcRegistry { registry };
    let ctx = RpcContext {
        node: node.clone(),
        config,
        registry: &mut registry,
        modules: &mut modules,
        auth_module: &mut auth_module,
    };

    let RpcHooks { on_rpc_started, extend_rpc_modules } = hooks;

    ext(RpcModuleContainer {
        modules: ctx.modules,
        auth_module: ctx.auth_module,
        registry: ctx.registry,
    })?;
    extend_rpc_modules.extend_rpc_modules(ctx)?;

    Ok(RpcSetupContext {
        node,
        config,
        modules,
        auth_module,
        auth_config,
        registry,
        on_rpc_started,
        engine_events,
        engine_handle: beacon_engine_handle,
    })
}

/// Launches the RPC servers with the given context and an additional hook for extending
/// modules. Whether the auth server is launched depends on the CLI configuration.
pub async fn launch_add_ons_with<F>(
    self,
    ctx: AddOnsContext<'_, N>,
    ext: F,
) -> eyre::Result<RpcHandle<N, EthB::EthApi>>
where
    F: FnOnce(RpcModuleContainer<'_, N, EthB::EthApi>) -> eyre::Result<()>,
{
    // Check CLI config to determine if auth server should be disabled
    let disable_auth = ctx.config.rpc.disable_auth_server;
    self.launch_add_ons_with_opt_engine(ctx, ext, disable_auth).await
}

/// Launches the RPC servers with the given context and an additional hook for extending
/// modules. Optionally disables the auth server based on the `disable_auth` parameter.
///
/// When `disable_auth` is true, the auth server will not be started and a noop handle
/// will be used instead.
pub async fn launch_add_ons_with_opt_engine<F>(
    self,
    ctx: AddOnsContext<'_, N>,
    ext: F,
    disable_auth: bool,
) -> eyre::Result<RpcHandle<N, EthB::EthApi>>
where
    F: FnOnce(RpcModuleContainer<'_, N, EthB::EthApi>) -> eyre::Result<()>,
{
    let rpc_middleware = self.rpc_middleware.clone();
    let auth_http_middleware = self.auth_http_middleware.clone();
    let tokio_runtime = self.tokio_runtime.clone();
    let setup_ctx = self.setup_rpc_components(ctx, ext).await?;
    let RpcSetupContext {
        node,
        config,
        mut modules,
        mut auth_module,
        auth_config,
        mut registry,
        on_rpc_started,
        engine_events,
        engine_handle,
    } = setup_ctx;

    let server_config = config
        .rpc
        .rpc_server_config()
        .set_rpc_middleware(rpc_middleware)
        .with_tokio_runtime(tokio_runtime);

    let auth_config = auth_config.with_http_middleware(auth_http_middleware);

    let (rpc, auth) = if disable_auth {
        // Only launch the RPC server, use a noop auth handle
        let rpc = Self::launch_rpc_server_internal(server_config, &modules).await?;
        (rpc, AuthServerHandle::noop())
    } else {
        let auth_module_clone = auth_module.clone();
        // launch servers concurrently
        let (rpc, auth) = futures::future::try_join(
            Self::launch_rpc_server_internal(server_config, &modules),
            Self::launch_auth_server_internal(auth_config.start(auth_module_clone)),
        )
        .await?;
        (rpc, auth)
    };

    let handles = RethRpcServerHandles { rpc, auth };

    Self::finalize_rpc_setup(
        &mut registry,
        &mut modules,
        &mut auth_module,
        &node,
        config,
        on_rpc_started,
        handles.clone(),
    )?;

    Ok(RpcHandle {
        rpc_server_handles: handles,
        rpc_registry: registry,
        engine_events,
        beacon_engine_handle: engine_handle,
        engine_shutdown: EngineShutdown::default(),
    })
}

/// Helper to launch the RPC server
async fn launch_rpc_server_internal<M>(
    server_config: RpcServerConfig<M>,
    modules: &TransportRpcModules,
) -> eyre::Result<RpcServerHandle>
where
    M: RethRpcMiddleware,
{
    let handle = server_config.start(modules).await?;

    if let Some(path) = handle.ipc_endpoint() {
        info!(target: "reth::cli", %path, "RPC IPC server started");
    }
    if let Some(addr) = handle.http_local_addr() {
        info!(target: "reth::cli", url=%addr, "RPC HTTP server started");
    }
    if let Some(addr) = handle.ws_local_addr() {
        info!(target: "reth::cli", url=%addr, "RPC WS server started");
    }

    Ok(handle)
}

/// Helper to launch the auth server
async fn launch_auth_server_internal(
    start_fut: impl Future<Output = Result<AuthServerHandle, reth_rpc_builder::error::RpcError>>,
) -> eyre::Result<AuthServerHandle> {
    start_fut
        .await
        .map_err(Into::into)
        .inspect(|handle| {
            let addr = handle.local_addr();
            if let Some(ipc_endpoint) = handle.ipc_endpoint() {
                info!(target: "reth::cli", url=%addr, ipc_endpoint=%ipc_endpoint, "RPC auth server started");
            } else {
                info!(target: "reth::cli", url=%addr, "RPC auth server started");
            }
        })
}

    /// Execute the configured cli command.
    ///
    /// This accepts a closure that is used to launch the node via the
    /// [`NodeCommand`](reth_cli_commands::node::NodeCommand).
    pub fn run(self, launcher: impl Launcher<C, Ext>) -> Result<()>
    where
        C: ChainSpecParser<ChainSpec = ChainSpec>,
    {
        let jit_args = match &self.cli.command {
            Commands::ReExecute(cmd) => cmd.jit.clone(),
            _ => Default::default(),
        };

        let components = move |spec: Arc<ChainSpec>| {
            let (evm_config, _) =
                reth_node_ethereum::node::build_evm_config(spec.clone(), &jit_args, None)
                    .expect("failed to start revmc JIT backend");
            (evm_config, Arc::new(EthBeaconConsensus::new(spec)))
        };

        self.run_with_components::<EthereumNode>(components, async move |builder, ext| {
            launcher.entrypoint(builder, ext).await
        })
    }

    /// Execute the configured cli command with the provided [`CliComponentsBuilder`].
    ///
    /// This accepts a closure that is used to launch the node via the
    /// [`NodeCommand`](reth_cli_commands::node::NodeCommand) and allows providing custom
    /// components.
    pub fn run_with_components<N>(
        mut self,
        components: impl CliComponentsBuilder<N>,
        launcher: impl AsyncFnOnce(
            WithLaunchContext<NodeBuilder<DatabaseEnv, C::ChainSpec>>,
            Ext,
        ) -> Result<()>,
    ) -> Result<()>
    where
        N: CliNodeTypes<Primitives: NodePrimitives<BlockHeader: HeaderMut>, ChainSpec: Hardforks>,
        C: ChainSpecParser<ChainSpec = N::ChainSpec>,
    {
        let runner = match self.runner.take() {
            Some(runner) => runner,
            None => {
                let runtime_config = match &self.cli.command {
                    Commands::Node(command) => {
                        reth_tasks::RuntimeConfig::default().with_rayon(RayonConfig {
                            reserved_cpu_cores: command.engine.reserved_cpu_cores,
                            proof_storage_worker_threads: command.engine.storage_worker_count,
                            proof_account_worker_threads: command.engine.account_worker_count,
                            prewarming_threads: command.engine.prewarming_threads,
                            ..Default::default()
                        })
                    }
                    _ => reth_tasks::RuntimeConfig::default(),
                };
                CliRunner::try_with_runtime_config(runtime_config)?
            }
        };

        // Add network name if available to the logs dir
        if let Some(chain_spec) = self.cli.command.chain_spec() {
            self.cli.logs.log_file_directory =
                self.cli.logs.log_file_directory.join(chain_spec.chain().to_string());
        }

        // Apply node-specific log defaults before initializing tracing
        if matches!(self.cli.command, Commands::Node(_)) {
            self.cli.logs.apply_node_defaults();
        }

        self.init_tracing(&runner)?;

        // Deprioritize background threads spawned by tracing/OTel libraries.
        reth_tasks::utils::deprioritize_background_threads();

        // Install the prometheus recorder to be sure to record all metrics
        install_prometheus_recorder();

        run_commands_with::<C, Ext, Rpc, N, SubCmd>(self.cli, runner, components, launcher)
    }

    /// Initializes tracing with the configured options.
    ///
    /// See [`Cli::init_tracing`] for more information.
    pub fn init_tracing(&mut self, runner: &CliRunner) -> Result<()> {
        if let Some(layers) = self.layers.take() {
            self.guard = Some(self.cli.init_tracing(runner, layers)?);
        }

        Ok(())
    }
}

/// Creates a new [`EngineApiTreeHandler`] instance and spawns it in its
/// own thread.
///
/// Returns the sender through which incoming requests can be sent to the task and the receiver
/// end of a [`EngineApiEvent`] unbounded channel to receive events from the engine.
#[expect(clippy::complexity)]
pub fn spawn_new(
    provider: P,
    consensus: Arc<dyn FullConsensus<N>>,
    payload_validator: V,
    persistence: PersistenceHandle<N>,
    payload_builder: PayloadBuilderHandle<T>,
    canonical_in_memory_state: CanonicalInMemoryState<N>,
    overlay_manager: OverlayManager<N>,
    config: TreeConfig,
    kind: EngineApiKind,
    evm_config: C,
    runtime: reth_tasks::Runtime,
) -> (Sender<FromEngine<EngineApiRequest<T, N>, N::Block>>, UnboundedReceiver<EngineApiEvent<N>>)
{
    let best_block_number = provider.best_block_number().unwrap_or(0);
    let header = provider.sealed_header(best_block_number).ok().flatten().unwrap_or_default();

    let persistence_state = PersistenceState {
        last_persisted_block: BlockNumHash::new(best_block_number, header.hash()),
        last_state_trie_persisted_block: BlockNumHash::new(best_block_number, header.hash()),
        rx: None,
    };

    let (tx, outgoing) = unbounded_channel();
    let state = EngineApiTreeState::new(
        config.block_buffer_limit(),
        config.max_invalid_header_cache_length(),
        config.invalid_header_hit_eviction_threshold(),
        header.num_hash(),
        kind,
        overlay_manager,
    );

    let task = Self::new(
        provider,
        consensus,
        payload_validator,
        tx,
        state,
        canonical_in_memory_state,
        persistence,
        persistence_state,
        payload_builder,
        config,
        kind,
        evm_config,
        runtime,
    );
    let incoming = task.incoming_tx.clone();
    spawn_os_thread("engine", || {
        increase_thread_priority();
        task.run()
    });
    (incoming, outgoing)
}

    fn poll_next_event(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<ChainEvent<T::Event>> {
        let this = self.get_mut();

        // This loop polls the components
        //
        // 1. Polls the backfill sync to completion, if active.
        // 2. Advances the chain by polling the handler.
        'outer: loop {
            // try to poll the backfill sync to completion, if active
            match this.backfill_sync.poll(cx) {
                Poll::Ready(backfill_sync_event) => match backfill_sync_event {
                    BackfillEvent::Started(_) => {
                        // notify handler that backfill sync started
                        this.handler.on_event(FromOrchestrator::BackfillSyncStarted);
                        return Poll::Ready(ChainEvent::BackfillSyncStarted);
                    }
                    BackfillEvent::Finished(res) => {
                        return match res {
                            Ok(ctrl) => {
                                tracing::debug!(?ctrl, "backfill sync finished");
                                // notify handler that backfill sync finished
                                this.handler.on_event(FromOrchestrator::BackfillSyncFinished(ctrl));
                                Poll::Ready(ChainEvent::BackfillSyncFinished)
                            }
                            Err(err) => {
                                tracing::error!( %err, "backfill sync failed");
                                Poll::Ready(ChainEvent::FatalError)
                            }
                        }
                    }
                    BackfillEvent::TaskDropped(err) => {
                        tracing::error!( %err, "backfill sync task dropped");
                        return Poll::Ready(ChainEvent::FatalError);
                    }
                },
                Poll::Pending => {}
            }

            // poll the handler for the next event
            match this.handler.poll(cx) {
                Poll::Ready(handler_event) => {
                    match handler_event {
                        HandlerEvent::BackfillAction(action) => {
                            // forward action to backfill_sync
                            this.backfill_sync.on_action(action);
                        }
                        HandlerEvent::Event(ev) => {
                            // bubble up the event
                            return Poll::Ready(ChainEvent::Handler(ev));
                        }
                        HandlerEvent::FatalError => {
                            error!(target: "engine::tree", "Fatal error");
                            return Poll::Ready(ChainEvent::FatalError)
                        }
                    }
                }
                Poll::Pending => {
                    // no more events to process
                    break 'outer
                }
            }
        }

        Poll::Pending
    }
}

impl<T, P> Stream for ChainOrchestrator<T, P>
where
    T: ChainHandler + Unpin,
    P: BackfillSync + Unpin,
{
    type Item = ChainEvent<T::Event>;

    fn poll_next(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        self.as_mut().poll_next_event(cx).map(Some)
    }
}

impl<T, S, D> ChainHandler for EngineHandler<T, S, D>
where
    T: EngineRequestHandler<Block = D::Block>,
    S: Stream + Send + Sync + Unpin + 'static,
    <S as Stream>::Item: Into<T::Request>,
    D: BlockDownloader,
{
    type Event = T::Event;

    fn on_event(&mut self, event: FromOrchestrator) {
        // delegate event to the handler
        self.handler.on_event(event.into());
    }

    fn poll(&mut self, cx: &mut Context<'_>) -> Poll<HandlerEvent<Self::Event>> {
        loop {
            // drain the handler first
            while let Poll::Ready(ev) = self.handler.poll(cx) {
                match ev {
                    RequestHandlerEvent::HandlerEvent(ev) => {
                        return match ev {
                            HandlerEvent::BackfillAction(target) => {
                                // bubble up backfill sync request
                                self.downloader.on_action(DownloadAction::Clear);
                                Poll::Ready(HandlerEvent::BackfillAction(target))
                            }
                            HandlerEvent::Event(ev) => {
                                // bubble up the event
                                Poll::Ready(HandlerEvent::Event(ev))
                            }
                            HandlerEvent::FatalError => Poll::Ready(HandlerEvent::FatalError),
                        }
                    }
                    RequestHandlerEvent::Download(req) => {
                        // delegate download request to the downloader
                        self.downloader.on_action(DownloadAction::Download(req));
                    }
                }
            }

            // pop the next incoming request
            if let Poll::Ready(Some(req)) = self.incoming_requests.poll_next_unpin(cx) {
                // and delegate the request to the handler
                self.handler.on_event(FromEngine::Request(req.into()));
                // skip downloading in this iteration to allow the handler to process the request
                continue
            }

            // advance the downloader
            if let Poll::Ready(outcome) = self.downloader.poll(cx) {
                if let DownloadOutcome::Blocks(blocks) = outcome {
                    // delegate the downloaded blocks to the handler
                    self.handler.on_event(FromEngine::DownloadedBlocks(blocks));
                }
                continue
            }

            return Poll::Pending
        }
    }
}

impl<Request, N: NodePrimitives> EngineRequestHandler for EngineApiRequestHandler<Request, N>
where
    Request: Send,
{
    type Event = ConsensusEngineEvent<N>;
    type Request = Request;
    type Block = N::Block;

    fn on_event(&mut self, event: FromEngine<Self::Request, Self::Block>) {
        // delegate to the tree
        let _ = self.to_tree.send(event);
    }

    fn poll(&mut self, cx: &mut Context<'_>) -> Poll<RequestHandlerEvent<Self::Event>> {
        let Some(ev) = ready!(self.from_tree.poll_recv(cx)) else {
            return Poll::Ready(RequestHandlerEvent::HandlerEvent(HandlerEvent::FatalError))
        };

        let ev = match ev {
            EngineApiEvent::BeaconConsensus(ev) => {
                RequestHandlerEvent::HandlerEvent(HandlerEvent::Event(ev))
            }
            EngineApiEvent::BackfillAction(action) => {
                RequestHandlerEvent::HandlerEvent(HandlerEvent::BackfillAction(action))
            }
            EngineApiEvent::Download(action) => RequestHandlerEvent::Download(action),
        };
        Poll::Ready(ev)
    }
}

impl<Node, Pool> NetworkBuilder<Node, Pool> for EthereumNetworkBuilder
where
    Node: FullNodeTypes<Types: NodeTypes<ChainSpec: Hardforks>>,
    Pool: TransactionPool<Transaction: PoolTransaction<Consensus = TxTy<Node::Types>>>
        + Unpin
        + 'static,
{
    type Network =
        NetworkHandle<BasicNetworkPrimitives<PrimitivesTy<Node::Types>, PoolPooledTx<Pool>>>;

    async fn build_network(
        self,
        ctx: &BuilderContext<Node>,
        pool: Pool,
    ) -> eyre::Result<Self::Network> {
        let network = ctx.network_builder().await?;
        let handle = ctx.start_network(network, pool);
        info!(target: "reth::cli", enode=%handle.local_node_record(), "P2P networking initialized");
