/// Convenience function to start the network tasks.
///
/// Spawns the configured network and associated tasks and returns the [`NetworkHandle`]
/// connected to that network.
pub fn start_network<N, Pool>(
    &self,
    builder: NetworkBuilder<(), (), N>,
    pool: Pool,
) -> NetworkHandle<N>
where
    N: NetworkPrimitives,
    Pool: TransactionPool<
            Transaction: PoolTransaction<
                Consensus = N::BroadcastedTransaction,
                Pooled = N::PooledTransaction,
            >,
        > + Unpin
        + 'static,
    Node::Provider: BlockReaderFor<N>,
{
    self.start_network_with(
        builder,
        pool,
        self.config().network.transactions_manager_config(),
        self.config().network.tx_propagation_policy,
    )
}

/// Convenience function to start the network tasks.
///
/// Accepts the config for the transaction task and the policy for propagation.
/// Uses the default [`StrictEthAnnouncementFilter`] for announcement filtering.
///
/// Spawns the configured network and associated tasks and returns the [`NetworkHandle`]
/// connected to that network.
pub fn start_network_with<Pool, N, Policy>(
    &self,
    builder: NetworkBuilder<(), (), N>,
    pool: Pool,
    tx_config: TransactionsManagerConfig,
    propagation_policy: Policy,
) -> NetworkHandle<N>
where
    N: NetworkPrimitives,
    Pool: TransactionPool<
            Transaction: PoolTransaction<
                Consensus = N::BroadcastedTransaction,
                Pooled = N::PooledTransaction,
            >,
        > + Unpin
        + 'static,
    Node::Provider: BlockReaderFor<N>,
    Policy: TransactionPropagationPolicy<N>,
{
    self.start_network_with_policies(
        builder,
        pool,
        tx_config,
        propagation_policy,
        StrictEthAnnouncementFilter::default(),
    )
}

/// Convenience function to start the network tasks with custom policies.
///
/// Accepts the config for the transaction task, the policy for propagation,
/// and a custom announcement filter. This is useful for configuring which tx types are accepted
/// in announcements.
///
/// Spawns the configured network and associated tasks and returns the [`NetworkHandle`]
/// connected to that network.
pub fn start_network_with_policies<Pool, N, PropPolicy, AnnPolicy>(
    &self,
    builder: NetworkBuilder<(), (), N>,
    pool: Pool,
    tx_config: TransactionsManagerConfig,
    propagation_policy: PropPolicy,
    announcement_policy: AnnPolicy,
) -> NetworkHandle<N>
where
    N: NetworkPrimitives,
    Pool: TransactionPool<
            Transaction: PoolTransaction<
                Consensus = N::BroadcastedTransaction,
                Pooled = N::PooledTransaction,
            >,
        > + Unpin
        + 'static,
    Node::Provider: BlockReaderFor<N>,
    PropPolicy: TransactionPropagationPolicy<N>,
    AnnPolicy: AnnouncementFilteringPolicy<N>,
{
    let (handle, network, txpool, eth) = builder
        .transactions_with_policies(
            pool.clone(),
            tx_config,
            propagation_policy,
            announcement_policy,
        )
        .map_transactions(|transactions| {
            if let Some(cache) = self.sender_recovery_cache.clone() {
                transactions.with_sender_recovery_cache(cache)
            } else {
                transactions
            }
        })
        .request_handler_with_blob_store(self.provider().clone(), pool.blob_store())
        .split_with_handle();

    self.executor.spawn_critical_blocking_task("p2p txpool", txpool);
    self.executor.spawn_critical_blocking_task("p2p eth request handler", eth);

    let default_peers_path = self.config().datadir().known_peers();
    let known_peers_file = self.config().network.persistent_peers_file(default_peers_path);
    self.executor.spawn_critical_with_graceful_shutdown_signal(
        "p2p network task",
        |shutdown| {
            network.run_until_graceful_shutdown(shutdown, |network| {
                if let Some(peers_file) = known_peers_file {
                    let num_known_peers = network.num_known_peers();
                    trace!(target: "reth::cli", peers_file=?peers_file, num_peers=%num_known_peers, "Saving current peers");
                    match network.write_peers_to_file(peers_file.as_path()) {
                        Ok(_) => {
                            info!(target: "reth::cli", peers_file=?peers_file, "Wrote network peers to file");
                        }
                        Err(err) => {
                            warn!(target: "reth::cli", %err, "Failed to write network peers to file");
                        }
                    }
                }
            })
        },
    );

    handle
}

impl<Node, Pool, PB, EvmConfig> PayloadServiceBuilder<Node, Pool, EvmConfig>
    for BasicPayloadServiceBuilder<PB>
where
    Node: FullNodeTypes,
    Pool: TransactionPool,
    EvmConfig: Send,
    PB: PayloadBuilderBuilder<Node, Pool, EvmConfig>,
{
    async fn spawn_payload_builder_service(
        self,
        ctx: &BuilderContext<Node>,
        pool: Pool,
        evm_config: EvmConfig,
    ) -> eyre::Result<PayloadBuilderHandle<<Node::Types as NodeTypes>::Payload>> {
        let Self { payload_builder_builder, pre_cache_state } = self;
        let payload_builder =
            payload_builder_builder.build_payload_builder(ctx, pool, evm_config).await?;

        let conf = ctx.config().builder.clone();

        let payload_job_config = BasicPayloadJobGeneratorConfig::default()
            .interval(conf.interval)
            .deadline(conf.deadline)
            .max_payload_tasks(conf.max_payload_tasks)
            .pre_cache_state(pre_cache_state);

        let payload_generator = BasicPayloadJobGenerator::with_builder(
            ctx.provider().clone(),
            ctx.task_executor().clone(),
            payload_job_config,
            payload_builder,
        );
        let (payload_service, payload_service_handle) =
            PayloadBuilderService::<_, _, <Node::Types as NodeTypes>::Payload>::new(
                payload_generator,
                ctx.provider().canonical_state_stream(),
            );

        ctx.task_executor().spawn_critical_os_thread(
            "payload-service",
            "payload builder service",
            payload_service,
        );

        Ok(payload_service_handle)
    }
}

pub fn new(
    pool: Pool,
    max_batch_size: usize,
) -> (Self, mpsc::UnboundedSender<BatchTxRequest<Pool::Transaction>>) {
    let (request_tx, request_rx) = mpsc::unbounded_channel();

    let processor = Self { pool, max_batch_size, buf: Vec::with_capacity(1), request_rx };

    (processor, request_tx)
}

pub fn configure(self) -> CliApp<C, Ext, Rpc, SubCmd> {
